contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint putAmount, uint lockTime, uint collectAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (putAmount)); require(putAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= putAmount, "not enough balance");
        c.Put{value: putAmount}(lockTime); if (__ESBMC_reverted()) return;

        (uint unlockBefore, uint balanceBefore) = c.Acc(address(this)); if (__ESBMC_reverted()) return;
        uint cBalBefore = address(c).balance;

        bool reverted;
        c.Collect(collectAmount); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        (uint unlockAfter, uint balanceAfter) = c.Acc(address(this)); if (__ESBMC_reverted()) return;
        uint cBalAfter = address(c).balance;

        assert(!(!reverted && unlockBefore < block.timestamp && balanceBefore >= c.MinSum() && balanceBefore >= collectAmount) || (balanceAfter == balanceBefore - collectAmount && (address(c).balance == cBalBefore - collectAmount || address(c).balance == cBalBefore - collectAmount + 0)));
    }

    receive() external payable {}
}

