pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MONEY_BOX c;

    function setUp() public {
        c = new MONEY_BOX();
    }

    function _run(uint256 putAmount, uint256 lockTime, uint256 collectAmount) internal {
        putAmount = bound(putAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= putAmount);
        try c.Put{value: putAmount}(lockTime) {} catch { return; }
        uint256 unlockBefore;
        uint256 balanceBefore;
        try c.Acc(address(this)) returns (uint256 __r0, uint256 __r1) { unlockBefore = __r0; balanceBefore = __r1; } catch { return; }
        uint cBalBefore = address(c).balance;
        bool reverted;
        try c.Collect(collectAmount) { reverted = false; } catch { reverted = true; }
        uint256 unlockAfter;
        uint256 balanceAfter;
        try c.Acc(address(this)) returns (uint256 __r0, uint256 __r1) { unlockAfter = __r0; balanceAfter = __r1; } catch { return; }
        uint cBalAfter = address(c).balance;
        assertTrue(!(!reverted && unlockBefore < block.timestamp && balanceBefore >= c.MinSum() && balanceBefore >= collectAmount) || (balanceAfter == balanceBefore - collectAmount && (address(c).balance == cBalBefore - collectAmount || address(c).balance == cBalBefore - collectAmount + 0)));
    }

    function testFuzz_run(uint256 putAmount, uint256 lockTime, uint256 collectAmount) public {
        _run(putAmount, lockTime, collectAmount);
    }

    receive() external payable {}
}
